<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client';import { useMutation,useQuery,useQueryClient } from '@tanstack/vue-query';import { Copy,KeyRound } from '@lucide/vue';import { NButton,NInput } from 'naive-ui';import { ref } from 'vue';import { shopApi } from '../lib'
const code=ref('');const shown=ref<Record<number,string>>({});const error=ref('');const client=useQueryClient();const cards=useQuery({queryKey:['shop-cards'],queryFn:shopApi.cards});const claim=useMutation({mutationFn:()=>shopApi.claimCard(code.value.trim()),onSuccess:async()=>{code.value='';error.value='';await Promise.all([client.invalidateQueries({queryKey:['shop-cards']}),client.invalidateQueries({queryKey:['shop-services']})])},onError:e=>error.value=friendlyError(e)});async function reveal(id:number){try{shown.value={...shown.value,[id]:(await shopApi.revealCard(id)).code}}catch(e){error.value=friendlyError(e)}}async function copy(value:string){await navigator.clipboard.writeText(value);error.value=''}
</script>
<template><section class="cards-page"><header><p>REDEMPTION</p><h1 tabindex="-1">我的卡密</h1><span>卡密属于当前 Customer Entity，领取的服务也会归属该 Entity。</span></header><form @submit.prevent="claim.mutate()"><NInput v-model:value="code" size="large" autocomplete="off" placeholder="输入卡密"/><NButton attr-type="submit" size="large" type="primary" :disabled="!code.trim()" :loading="claim.isPending.value">领取权益</NButton></form><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="cards.isPending.value" class="cards-state" role="status">正在读取卡密…</div><div v-else-if="cards.isError.value" class="cards-state" role="alert"><strong>卡密暂时没有加载出来</strong><NButton secondary @click="cards.refetch()">重新加载</NButton></div><div v-else-if="!cards.data.value?.length" class="cards-state"><KeyRound :size="30"/><strong>还没有卡密</strong><span>购买卡密商品后，未使用的兑换码会显示在这里；也可以直接输入已有兑换码领取服务。</span></div><div v-else class="card-list"><article v-for="card in cards.data.value" :key="card.id"><KeyRound/><div><small>{{card.campaign.name}}</small><strong>{{shown[card.id]||card.code_hint}}</strong><span>已使用 {{card.use_count}} 次</span></div><NButton v-if="!shown[card.id]" secondary @click="reveal(card.id)">查看</NButton><NButton v-else secondary @click="copy(shown[card.id])"><template #icon><Copy :size="16"/></template>复制</NButton></article></div></section></template>
<style scoped>.cards-page{width:min(900px,calc(100% - 32px));margin:auto;padding:64px 0 96px}.cards-page h1{font-size:clamp(2rem,5vw,3.6rem);margin:8px 0}.cards-page header p{color:#69e4dc;letter-spacing:.12em}.cards-page header span,.card-list span,.cards-state span{color:#9fb0c5}.cards-page form{display:grid;grid-template-columns:1fr auto;gap:10px;margin:32px 0}.card-list{display:grid;overflow:hidden;border-block:1px solid #263951}.card-list article{min-height:88px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:16px;padding:16px 8px;border-bottom:1px solid #263951}.card-list article:last-child{border-bottom:0}.card-list strong,.card-list span{display:block;margin-top:4px}.cards-state{min-height:180px;display:grid;place-items:center;align-content:center;gap:.75rem;padding:24px;text-align:center;border-block:1px solid #263951}.error{color:#ff8d93}@media(max-width:600px){.cards-page form{grid-template-columns:1fr}.card-list article{grid-template-columns:auto 1fr}.card-list button{grid-column:2}}</style>
